namespace Intropy.Topology.Model;

/// <summary>
/// One component in the system: an integration block or a container service, together
/// with all of its edges and one activation attribute — an optional cron schedule.
/// Everything else about the workload shape (hosting model, ports,
/// process lifetime) lives in the component's own scaffold, not in the topology.
/// </summary>
public sealed record ComponentModel
{
    /// <summary>The component's name (K8s resource name / Dapr app-id).</summary>
    public required string Name { get; init; }

    /// <summary>The component kind this component was declared as.</summary>
    public required ComponentKind Kind { get; init; }

    /// <summary>The cron schedule that activates the component; null when it runs once
    /// at host start.</summary>
    public required string? Schedule { get; init; }

    /// <summary>Topics the component subscribes to.</summary>
    public required IReadOnlyList<TopicSubscription> Subscribes { get; init; }

    /// <summary>Topics the component publishes to, by output port.</summary>
    public required IReadOnlyList<PublishEdge> Publishes { get; init; }

    /// <summary>Connectors the component uses (explicit From/To usage).</summary>
    public required IReadOnlyList<ConnectorEdge> Connectors { get; init; }

    /// <summary>External platform-service app IDs the component invokes.</summary>
    public required IReadOnlyList<string> Uses { get; init; }
}

namespace Intropy.Topology.Model;

/// <summary>A topic a component subscribes to.</summary>
public sealed record TopicSubscription
{
    /// <summary>The Dapr pubsub component name.</summary>
    public required string PubSubName { get; init; }

    /// <summary>The topic name.</summary>
    public required string TopicName { get; init; }
}

/// <summary>A component publishing to a topic through a named output port.</summary>
public sealed record PublishEdge
{
    /// <summary>The output port name (<c>default</c> when no port was given).</summary>
    public required string Port { get; init; }

    /// <summary>The Dapr pubsub component name.</summary>
    public required string PubSubName { get; init; }

    /// <summary>The topic name.</summary>
    public required string TopicName { get; init; }
}

/// <summary>A component using a connector in one direction.</summary>
public sealed record ConnectorEdge
{
    /// <summary>The connector's name.</summary>
    public required string ConnectorName { get; init; }

    /// <summary>The direction the connector is used in.</summary>
    public required ConnectorDirection Direction { get; init; }
}

using System.Text.Json.Serialization;

namespace Intropy.Topology.Model;

/// <summary>
/// A topic materialized from usage, with its publishing and subscribing component names
/// precomputed in ordinal sort order.
/// </summary>
public sealed record TopicResource
{
    /// <summary>The Dapr pubsub component name.</summary>
    public required string PubSubName { get; init; }

    /// <summary>The topic name.</summary>
    public required string TopicName { get; init; }

    /// <summary>Full name of the event contract type carried on the topic.</summary>
    public required string ContractTypeName { get; init; }

    /// <summary>Names of components publishing to the topic (sorted).</summary>
    public required IReadOnlyList<string> Publishers { get; init; }

    /// <summary>Names of components subscribed to the topic (sorted).</summary>
    public required IReadOnlyList<string> Subscribers { get; init; }
}

/// <summary>An external platform service materialized from component usage.</summary>
public sealed record ServiceResource
{
    /// <summary>The Dapr app ID callers invoke.</summary>
    public required string AppId { get; init; }

    /// <summary>Names of components invoking this service, sorted ordinally.</summary>
    public required IReadOnlyList<string> Consumers { get; init; }
}

/// <summary>A system-owned connector materialized from usage.</summary>
public sealed record ConnectorResource
{
    /// <summary>The connector's name (DNS-1123 label).</summary>
    public required string Name { get; init; }

    /// <summary>The deployed transport shape — the kind of Dapr binding the connector materializes as after deployment.</summary>
    public required Transport Transport { get; init; }

    /// <summary>The derived Dapr binding component name: <c>binding.&lt;connector-name&gt;</c>.</summary>
    public string DaprComponentName => $"binding.{Name}";

    /// <summary>The union of directions the connector is used in.</summary>
    public required IReadOnlyList<ConnectorDirection> Directions { get; init; }

    /// <summary>Names of components using the connector (sorted).</summary>
    public required IReadOnlyList<string> UsedBy { get; init; }
}

using Intropy.Topology.Model;

namespace Intropy.Topology;

/// <summary>
/// Represents a declared topology component and its recorded edges. Declaration methods
/// record intent; <see cref="SystemBuilder.Build"/> performs completeness and
/// cross-component validation. Instances are mutable during declaration and not thread-safe.
/// </summary>
public abstract class Component
{
    /// <summary>The output port name recorded for every <c>Publishes</c> call.</summary>
    internal const string DefaultPort = "default";

    private readonly List<TopicRef> _subscribes = [];
    private readonly List<(string Port, TopicRef Topic)> _publishes = [];
    private readonly List<(ConnectorRef Connector, ConnectorDirection Direction)> _connectors = [];
    private readonly List<ServiceRef> _services = [];

    private protected Component(string name, ComponentKind kind)
    {
        Name = name;
        Kind = kind;
    }

    /// <summary>The component's name (K8s resource name / Dapr app-id).</summary>
    public string Name { get; }

    /// <summary>The component's block kind.</summary>
    public ComponentKind Kind { get; }

    /// <summary>The cron schedule recorded by <c>WithSchedule</c>; null when the component
    /// runs once at host start. A later call replaces the value. Syntax is validated at
    /// <see cref="SystemBuilder.Build"/>.</summary>
    internal string? ScheduleCall { get; private set; }

    internal IReadOnlyList<TopicRef> SubscribeCalls => _subscribes;

    internal IReadOnlyList<(string Port, TopicRef Topic)> PublishCalls => _publishes;

    internal IReadOnlyList<(ConnectorRef Connector, ConnectorDirection Direction)> ConnectorCalls => _connectors;

    internal IReadOnlyList<ServiceRef> ServiceCalls => _services;

    internal void AddSubscribe(TopicRef topic)
    {
        ArgumentNullException.ThrowIfNull(topic);
        _subscribes.Add(topic);
    }

    internal void AddPublish(TopicRef topic)
    {
        ArgumentNullException.ThrowIfNull(topic);
        _publishes.Add((DefaultPort, topic));
    }

    internal void AddConnector(ConnectorRef connector, ConnectorDirection direction)
    {
        ArgumentNullException.ThrowIfNull(connector);
        _connectors.Add((connector, direction));
    }

    internal void AddService(ServiceRef service)
    {
        ArgumentNullException.ThrowIfNull(service);
        _services.Add(service);
    }

    internal void SetSchedule(string cron)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(cron);
        ScheduleCall = cron;
    }
}

/// <summary>The declared extractor: an edge block that pulls or receives data from an
/// external system and publishes it. Obtained from the extractor builder's
/// <c>Component</c> property.</summary>
public sealed class ExtractorComponent : Component
{
    internal ExtractorComponent(string name) : base(name, ComponentKind.Extractor) { }
}

/// <summary>The declared loader: an edge block that consumes exactly one topic and writes
/// to an external system. Obtained from the loader builder's <c>Component</c> property.</summary>
public sealed class LoaderComponent : Component
{
    internal LoaderComponent(string name) : base(name, ComponentKind.Loader) { }
}

/// <summary>The declared transactional integration: a synchronous block that reads/writes
/// external systems through connectors. Obtained from the integration builder's
/// <c>Component</c> property.</summary>
public sealed class TransactionalIntegrationComponent : Component
{
    internal TransactionalIntegrationComponent(string name)
        : base(name, ComponentKind.TransactionalIntegration) { }
}

using System.Diagnostics.CodeAnalysis;
using System.Text.Json.Serialization;
using Intropy.Topology.Validation;

namespace Intropy.Topology;

/// <summary>
/// Identifies a pub/sub topic by its Dapr component and topic names. The backing
/// resource materializes only when a component uses the reference.
/// </summary>
public abstract record TopicRef
{
    /// <summary>The Dapr pubsub component name (DNS-1123 subdomain).</summary>
    public string PubSubName { get; }

    /// <summary>The topic name within the pubsub (DNS-1123 subdomain).</summary>
    public string TopicName { get; }

    /// <summary>The event contract type carried on the topic.</summary>
    public abstract Type ContractType { get; }

    private protected TopicRef(string pubSubName, string topicName)
    {
        PubSubName = NameRules.RequireSubdomain(pubSubName, nameof(pubSubName));
        TopicName = NameRules.RequireSubdomain(topicName, nameof(topicName));
    }
}

/// <summary>
/// A <see cref="TopicRef"/> whose generic argument identifies the event contract. Topology
/// wiring uses the topic names, while <see cref="TopicRef.ContractType"/> exposes the type.
/// </summary>
/// <typeparam name="T">The event contract type published on the topic.</typeparam>
public sealed record TopicRef<T> : TopicRef
{
    /// <inheritdoc />
    public override Type ContractType => typeof(T);

    private TopicRef(string pubSubName, string topicName)
        : base(pubSubName, topicName)
    {
    }

    /// <summary>Declares a topic on a pubsub component.</summary>
    /// <param name="pubSubName">The Dapr pubsub component name (DNS-1123 subdomain).</param>
    /// <param name="topicName">The topic name (DNS-1123 subdomain).</param>
    /// <exception cref="ArgumentException">A name is not a valid DNS-1123 subdomain.</exception>
    public static TopicRef<T> Define(
        [ConstantExpected] string pubSubName,
        [ConstantExpected] string topicName) =>
        new(pubSubName, topicName);
}

/// <summary>
/// Identifies a platform service by the Dapr app ID callers use. The service materializes
/// from component usage; this reference neither owns nor deploys its provider.
/// </summary>
public sealed record ServiceRef
{
    /// <summary>The service's Dapr app ID (DNS-1123 label).</summary>
    public string AppId { get; }

    private ServiceRef(string appId) => AppId = NameRules.RequireLabel(appId, nameof(appId));

    /// <summary>Declares a reusable external platform-service identity.</summary>
    /// <param name="appId">The Dapr app ID callers invoke.</param>
    /// <exception cref="ArgumentException">The app ID is not a valid DNS-1123 label.</exception>
    public static ServiceRef Define([ConstantExpected] string appId) => new(appId);
}

/// <summary>
/// A connector — the named connection point between the system and the outside world.
/// Every edge block reaches the outside world through a connector. Its declared transport is
/// the deployed shape (value-free; connection values are environment-owned deployment
/// configuration); local F5 runs substitute their own resolution via the development
/// definition. The Dapr binding component's name is always derived
/// (<c>binding.&lt;connector-name&gt;</c>), never declared. Connectors are declared in the
/// SystemHost (typically a scaffolded <c>Connectors.cs</c>); they are system-owned and never
/// shared across systems. Direction is not part of the identity — it follows from usage
/// (<c>From</c> / <c>To</c>).
/// </summary>
public sealed record ConnectorRef
{
    /// <summary>The connector's name (DNS-1123 label, e.g. <c>pim</c>).</summary>
    public string Name { get; }

    /// <summary>The deployed transport shape — the kind of Dapr binding the connector materializes as after deployment.</summary>
    public Transport Transport { get; }

    private ConnectorRef(string name, Transport transport)
    {
        Name = name;
        Transport = transport;
    }

    /// <summary>Declares a connector with its deployed transport shape.</summary>
    /// <param name="name">The connector's name (DNS-1123 label).</param>
    /// <param name="transport">The value-free deployed Dapr binding transport shape.</param>
    /// <exception cref="ArgumentException">The name is not a valid DNS-1123 label.</exception>
    public static ConnectorRef Define([ConstantExpected] string name, Transport transport)
    {
        ArgumentNullException.ThrowIfNull(transport);
        return new ConnectorRef(NameRules.RequireLabel(name, nameof(name)), transport);
    }
}

/// <summary>
/// The kind of Dapr binding a connector materializes as. All connectivity goes through
/// Dapr — the transport selects the Dapr binding component's <c>spec.type</c>; it never
/// bypasses Dapr. The component name is always derived: <c>binding.&lt;connector-name&gt;</c>.
/// </summary>
[JsonPolymorphic(TypeDiscriminatorPropertyName = "$transport")]
[JsonDerivedType(typeof(SftpTransport), "sftp")]
[JsonDerivedType(typeof(DefaultTransport), "default")]
public abstract record Transport
{
    private protected Transport()
    {
    }

    /// <summary>The Dapr binding component's <c>spec.type</c> (e.g. <c>bindings.localstorage</c>).</summary>
    public abstract string DaprType { get; }

    /// <summary>Whether the transport can provide input to a component through <c>From</c>.</summary>
    [JsonIgnore]
    public abstract bool SupportsInput { get; }

    /// <summary>Whether the transport can accept component output through <c>To</c>.</summary>
    [JsonIgnore]
    public abstract bool SupportsOutput { get; }

    /// <summary>
    /// SFTP transport (<c>bindings.sftp</c>) for deployed environments. Its address,
    /// credentials, and path are supplied by deployment configuration.
    /// </summary>
    public static Transport Sftp() => new SftpTransport();

    /// <summary>
    /// Placeholder transport for scaffolded connectors whose deployed shape is not yet
    /// chosen. Compiles and passes capability checks so a freshly scaffolded system builds,
    /// runs locally, and generates local artifacts (local runs resolve every connector to
    /// localstorage regardless of transport); <c>task check</c> warns about it. Deployment
    /// generation must refuse it — replace with a concrete transport (e.g. <see cref="Sftp"/>)
    /// before deployment.
    /// </summary>
    public static Transport Default() => new DefaultTransport();
}

/// <summary>
/// Value-free SFTP transport: a Dapr binding component of type <c>bindings.sftp</c>.
/// Deployment configuration supplies its address, credentials, and path.
/// </summary>
public sealed record SftpTransport : Transport
{
    /// <inheritdoc />
    public override string DaprType => "bindings.sftp";

    /// <inheritdoc />
    [JsonIgnore]
    public override bool SupportsInput => true;

    /// <inheritdoc />
    [JsonIgnore]
    public override bool SupportsOutput => true;
}

/// <summary>
/// Placeholder transport: no real Dapr binding type. A scaffolded connector starts here
/// so the system compiles and runs locally immediately — local runs resolve every
/// connector to localstorage, so the declared transport is never consulted. <c>task
/// check</c> warns about it, and deployment generation must refuse to emit a component
/// for it. The developer replaces it with a concrete transport (e.g. <see cref="SftpTransport"/>)
/// before deployment.
/// </summary>
public sealed record DefaultTransport : Transport
{
    /// <inheritdoc />
    public override string DaprType => "";

    /// <inheritdoc />
    [JsonIgnore]
    public override bool SupportsInput => true;

    /// <inheritdoc />
    [JsonIgnore]
    public override bool SupportsOutput => true;
}

using System.Text;
using System.Text.Json;
using System.Text.Json.Serialization;
using Intropy.Topology.Model;

namespace Intropy.Topology.Generation;

/// <summary>A single generated artifact: a relative path and its text content.</summary>
/// <param name="RelativePath">Path relative to the output root (forward slashes).</param>
/// <param name="Content">The file's text content.</param>
public sealed record GeneratedFile(string RelativePath, string Content);

/// <summary>The artifacts generated for a system: Dapr component YAML and per-component runtime config.</summary>
public sealed class GeneratedArtifacts
{
    /// <summary>Subdirectory holding Dapr component YAML — the value for a sidecar's resources-path.</summary>
    public const string ComponentsDir = "components";

    /// <summary>Subdirectory holding per-component runtime config.</summary>
    public const string ConfigDir = "config";

    internal GeneratedArtifacts(IReadOnlyList<GeneratedFile> files) => Files = files;

    /// <summary>All generated files, in deterministic order.</summary>
    public IReadOnlyList<GeneratedFile> Files { get; }

    /// <summary>Writes every artifact under <paramref name="directory"/>, creating subdirectories.</summary>
    /// <param name="directory">The output root.</param>
    public void WriteTo(string directory)
    {
        ArgumentException.ThrowIfNullOrEmpty(directory);
        foreach (var file in Files)
        {
            var path = Path.Combine(directory, file.RelativePath.Replace('/', Path.DirectorySeparatorChar));
            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            File.WriteAllText(path, file.Content);
        }
    }
}

/// <summary>
/// Turns a validated <see cref="SystemTopology"/> into Dapr components and runtime config
/// for the local run profile: pub/sub backed by Redis Streams, file bindings anchored to the
/// SystemHost directory. Output order is deterministic.
/// </summary>
public static class TopologyGenerator
{
    // Schedule is the only emitted property that is ever null; omitting it keeps
    // unscheduled components' config free of a redundant attribute.
    private static readonly JsonSerializerOptions s_json = new()
    {
        WriteIndented = true,
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
    };

    /// <summary>Generates local artifacts, including validated development mock endpoints when declared.</summary>
    /// <param name="topology">The validated topology.</param>
    /// <param name="development">The optional validated development substitutions.</param>
    public static GeneratedArtifacts Generate(SystemTopology topology, DevelopmentManifest development)
    {
        ArgumentNullException.ThrowIfNull(topology);
        ArgumentNullException.ThrowIfNull(development);
        var files = new List<GeneratedFile>();

        foreach (var topic in topology.Topics.Select(t => t.PubSubName).Distinct(StringComparer.Ordinal))
        {
            files.Add(PubSubComponent(topic, topology));
        }

        // Local runs resolve every connector to localstorage, so the declared transport is
        // deliberately not consulted here: the placeholder default transport must not block
        // F5. Deployment generation is where an unresolved transport must hard-fail.
        foreach (var connector in topology.Connectors)
        {
            var resolution = development.Files.SingleOrDefault(file => file.ConnectorName == connector.Name);
            if (resolution is null)
            {
                throw new InvalidOperationException($"Connector '{connector.Name}' has no local file resolution in the development manifest.");
            }

            files.Add(BindingComponent(connector, resolution));
        }

        foreach (var mock in development.Mocks)
        {
            var service = topology.Services.Single(service => service.AppId == mock.AppId);
            files.Add(HttpEndpoint(mock, service));
        }

        foreach (var component in topology.Components)
        {
            files.Add(ComponentConfig(topology.SystemName, component));
        }

        return new GeneratedArtifacts(files);
    }

    private static GeneratedFile PubSubComponent(string pubSubName, SystemTopology topology)
    {
        var scopes = topology.Components
            .Where(c => c.Subscribes.Any(s => s.PubSubName == pubSubName) || c.Publishes.Any(p => p.PubSubName == pubSubName))
            .Select(c => c.Name)
            .OrderBy(n => n, StringComparer.Ordinal);

        // Redis Streams with consumer groups: an unacked or RETRY'd message is redelivered
        // after the component's redeliverInterval instead of being dropped. Port 6380 because
        // `dapr init` publishes its own dapr_redis on the host's 6379.
        var metadata = new[]
        {
            ("redisHost", "localhost:6380"),
        };
        var yaml = DaprYaml.Component(pubSubName, "pubsub.redis", metadata, scopes);
        return new GeneratedFile($"{GeneratedArtifacts.ComponentsDir}/{pubSubName}.yaml", yaml);
    }

    private static GeneratedFile BindingComponent(ConnectorResource connector, ConnectorFileResolution resolution)
    {
        // Local runs resolve every connector to a localstorage folder. The manifest path is
        // already absolute (anchored at the SystemHost directory); artifacts land in per-run
        // temp dirs and the sidecar's cwd is not guaranteed, so an absolute path is required.
        var metadata = new List<(string, string)> { ("rootPath", resolution.RootPath) };
        var yaml = DaprYaml.Component(
            connector.DaprComponentName, "bindings.localstorage", metadata, connector.UsedBy);
        return new GeneratedFile($"{GeneratedArtifacts.ComponentsDir}/{connector.DaprComponentName}.yaml", yaml);
    }

    private static GeneratedFile HttpEndpoint(OpenApiMock mock, ServiceResource service)
    {
        var yaml = DaprYaml.HttpEndpoint(mock.AppId, mock.BaseUri.AbsoluteUri, service.Consumers);
        return new GeneratedFile($"{GeneratedArtifacts.ComponentsDir}/{mock.AppId}.yaml", yaml);
    }

    private static GeneratedFile ComponentConfig(string systemName, ComponentModel component)
    {
        var config = new
        {
            Intropy = new
            {
                System = systemName,
                Component = component.Name,
                Kind = component.Kind.ToString(),
                component.Schedule,
                Subscribes = component.Subscribes.Select(s => new { s.PubSubName, s.TopicName }),
                Publishes = component.Publishes.Select(p => new { p.Port, p.PubSubName, p.TopicName }),
                Connectors = component.Connectors.Select(c => new
                {
                    c.ConnectorName,
                    Direction = c.Direction.ToString(),
                    DaprComponent = $"binding.{c.ConnectorName}",
                }),
                Uses = component.Uses,
            },
        };

        var json = JsonSerializer.Serialize(config, s_json);
        return new GeneratedFile($"{GeneratedArtifacts.ConfigDir}/{component.Name}.intropy.json", json);
    }
}

/// <summary>Minimal, deterministic emitter for Dapr <c>Component</c> YAML.</summary>
internal static class DaprYaml
{
    public static string HttpEndpoint(string name, string baseUrl, IEnumerable<string> scopes)
    {
        var sb = new StringBuilder();
        sb.Append("apiVersion: dapr.io/v1alpha1\n");
        sb.Append("kind: HTTPEndpoint\n");
        sb.Append("metadata:\n");
        sb.Append("  name: ").Append(Quote(name)).Append('\n');
        sb.Append("spec:\n");
        sb.Append("  baseUrl: ").Append(Quote(baseUrl)).Append('\n');
        sb.Append("scopes:\n");
        foreach (var scope in scopes.OrderBy(scope => scope, StringComparer.Ordinal))
        {
            sb.Append("- ").Append(Quote(scope)).Append('\n');
        }

        return sb.ToString();
    }

    public static string Component(
        string name,
        string type,
        IEnumerable<(string Key, string Value)> metadata,
        IEnumerable<string> scopes)
    {
        var meta = metadata.ToList();
        var scopeList = scopes.ToList();

        var sb = new StringBuilder();
        sb.Append("apiVersion: dapr.io/v1alpha1\n");
        sb.Append("kind: Component\n");
        sb.Append("metadata:\n");
        sb.Append("  name: ").Append(Quote(name)).Append('\n');
        sb.Append("spec:\n");
        sb.Append("  type: ").Append(Quote(type)).Append('\n');
        sb.Append("  version: v1\n");
        if (meta.Count == 0)
        {
            sb.Append("  metadata: []\n");
        }
        else
        {
            sb.Append("  metadata:\n");
            foreach (var (key, value) in meta)
            {
                sb.Append("  - name: ").Append(Quote(key)).Append('\n');
                sb.Append("    value: ").Append(Quote(value)).Append('\n');
            }
        }

        if (scopeList.Count > 0)
        {
            sb.Append("scopes:\n");
            foreach (var scope in scopeList)
            {
                sb.Append("- ").Append(Quote(scope)).Append('\n');
            }
        }

        return sb.ToString();
    }

    private static string Quote(string value) =>
        $"\"{value.Replace("\\", "\\\\", StringComparison.Ordinal).Replace("\"", "\\\"", StringComparison.Ordinal)}\"";
}

using System.Collections.Concurrent;
using Aspire.Hosting.ApplicationModel;
using Cronos;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

namespace Intropy.Topology.Aspire;

/// <summary>A component the scheduler re-runs: its resource name and cron expression.</summary>
internal sealed record ScheduledComponent(string Name, string Cron, IReadOnlyList<string>? Uses = null);

/// <summary>
/// The scheduler's view of the Aspire resource model: last known states plus start/wait
/// commands. A seam so tick behavior is unit-testable without DCP.
/// </summary>
internal interface IResourceLifecycle
{
    /// <summary>Maintains the last-known-state map; runs for the host's lifetime.</summary>
    Task WatchAsync(CancellationToken cancellationToken);

    /// <summary>Whether the resource can be started: never seen, or in a terminal state.
    /// A non-terminal state means a run is still in progress.</summary>
    bool IsStartable(string resourceName);

    /// <summary>Executes a resource command; false when the command fails or is unavailable.</summary>
    Task<bool> ExecuteAsync(string resourceName, string commandName, CancellationToken cancellationToken);

    /// <summary>Waits for the resource to reach Running; false on timeout.</summary>
    Task<bool> WaitUntilRunningAsync(string resourceName, TimeSpan timeout, CancellationToken cancellationToken);
}

/// <summary>Production <see cref="IResourceLifecycle"/> over the Aspire services.</summary>
internal sealed class AspireResourceLifecycle(
    ResourceCommandService commands,
    ResourceNotificationService notifications) : IResourceLifecycle
{
    private readonly ConcurrentDictionary<string, string?> _states = new(StringComparer.Ordinal);

    public async Task WatchAsync(CancellationToken cancellationToken)
    {
        await foreach (var evt in notifications.WatchAsync(cancellationToken).ConfigureAwait(false))
        {
            _states[evt.Resource.Name] = evt.Snapshot.State?.Text;
        }
    }

    public bool IsStartable(string resourceName)
    {
        var state = _states.GetValueOrDefault(resourceName);
        return state is null || KnownResourceStates.TerminalStates.Contains(state, StringComparer.Ordinal);
    }

    public async Task<bool> ExecuteAsync(string resourceName, string commandName, CancellationToken cancellationToken)
    {
        try
        {
            var result = await commands
                .ExecuteCommandAsync(resourceName, commandName, cancellationToken)
                .ConfigureAwait(false);
            return result.Success;
        }
        catch (Exception) when (!cancellationToken.IsCancellationRequested)
        {
            // Command unavailable in the resource's current state, or the resource is
            // unknown — the caller decides whether to fall back or give up on this tick.
            return false;
        }
    }

    public async Task<bool> WaitUntilRunningAsync(
        string resourceName, TimeSpan timeout, CancellationToken cancellationToken)
    {
        using var deadline = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        deadline.CancelAfter(timeout);
        try
        {
            await notifications
                .WaitForResourceAsync(resourceName, KnownResourceStates.Running, deadline.Token)
                .ConfigureAwait(false);
            return true;
        }
        catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
        {
            return false;
        }
    }
}

/// <summary>
/// Re-runs scheduled components on their cron ticks — the run backend's CronJob emulation.
/// Every component also runs once at host start via normal resource auto-start; this
/// service only owns the re-runs. Ticks fire in local time (the developer's wall clock,
/// unlike Kubernetes' UTC default), a tick that lands while the previous run is still in
/// progress is skipped with a warning (concurrencyPolicy: Forbid), and the sidecar is
/// started before the app because a run-to-completion block shuts its sidecar down when
/// it exits.
/// </summary>
internal sealed class ComponentScheduler(
    IReadOnlyList<ScheduledComponent> components,
    IResourceLifecycle lifecycle,
    TimeProvider timeProvider,
    ILogger<ComponentScheduler> logger,
    MockReadiness? mockReadiness = null) : BackgroundService
{
    private static readonly TimeSpan s_sidecarReadyTimeout = TimeSpan.FromMinutes(3);

    private readonly ConcurrentDictionary<string, SemaphoreSlim> _gates = new(StringComparer.Ordinal);

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        var loops = new List<Task> { WatchQuietlyAsync(stoppingToken) };
        loops.AddRange(components.Select(component => RunScheduleLoopAsync(component, stoppingToken)));
        await Task.WhenAll(loops).ConfigureAwait(false);
    }

    /// <summary>
    /// Starts the component's sidecar + app resource pair, unless the previous run is still
    /// in progress (skipped with a warning). Shared by cron ticks and the dashboard's
    /// "Run now" command.
    /// </summary>
    internal async Task TriggerAsync(string component, string reason, CancellationToken cancellationToken)
    {
        var gate = _gates.GetOrAdd(component, _ => new SemaphoreSlim(1, 1));
        if (!await gate.WaitAsync(0, cancellationToken).ConfigureAwait(false))
        {
            logger.LogWarning(
                "intropy-schedule: skipping {Reason} for {Component}: a trigger is already executing",
                reason, component);
            return;
        }

        try
        {
            if (mockReadiness is not null)
            {
                var uses = components.SingleOrDefault(candidate => candidate.Name == component)?.Uses ?? [];
                await mockReadiness.WaitForAsync(uses, TimeSpan.FromMinutes(3), cancellationToken).ConfigureAwait(false);
            }

            if (!lifecycle.IsStartable(component))
            {
                logger.LogWarning(
                    "intropy-schedule: skipping {Reason} for {Component}: the previous run is still in progress",
                    reason, component);
                return;
            }

            // The run-to-completion block shut its sidecar down when it exited, so bring
            // the sidecar back first — daprd must be accepting connections before the app
            // starts, or the app's first sidecar call fails.
            var sidecar = DaprSidecarIdentity.CliName(component);
            if (lifecycle.IsStartable(sidecar))
            {
                if (!await StartResourceAsync(sidecar, cancellationToken).ConfigureAwait(false))
                {
                    logger.LogError(
                        "intropy-schedule: could not start sidecar {Sidecar}; abandoning {Reason} for {Component}",
                        sidecar, reason, component);
                    return;
                }

                if (!await lifecycle.WaitUntilRunningAsync(sidecar, s_sidecarReadyTimeout, cancellationToken)
                        .ConfigureAwait(false))
                {
                    logger.LogError(
                        "intropy-schedule: sidecar {Sidecar} did not reach Running within {Timeout}; " +
                        "abandoning {Reason} for {Component}",
                        sidecar, s_sidecarReadyTimeout, reason, component);
                    return;
                }
            }

            if (!await StartResourceAsync(component, cancellationToken).ConfigureAwait(false))
            {
                logger.LogError("intropy-schedule: could not start {Component} ({Reason})", component, reason);
                return;
            }

            logger.LogInformation("intropy-schedule: triggered {Component} ({Reason})", component, reason);
        }
        finally
        {
            gate.Release();
        }
    }

    private async Task<bool> StartResourceAsync(string resourceName, CancellationToken cancellationToken)
    {
        // Start is right for a terminal/never-started resource; fall back to Restart to
        // absorb state races between our snapshot and DCP's.
        return await lifecycle.ExecuteAsync(resourceName, KnownResourceCommands.StartCommand, cancellationToken)
                   .ConfigureAwait(false)
               || await lifecycle.ExecuteAsync(resourceName, KnownResourceCommands.RestartCommand, cancellationToken)
                   .ConfigureAwait(false);
    }

    private async Task RunScheduleLoopAsync(ScheduledComponent component, CancellationToken stoppingToken)
    {
        try
        {
            while (!stoppingToken.IsCancellationRequested)
            {
                var now = timeProvider.GetUtcNow();
                var next = CronExpression.Parse(component.Cron).GetNextOccurrence(now, TimeZoneInfo.Local);
                if (next is null)
                {
                    logger.LogWarning(
                        "intropy-schedule: {Component}'s schedule '{Cron}' never fires again; stopping its loop",
                        component.Name, component.Cron);
                    return;
                }

                logger.LogInformation(
                    "intropy-schedule: {Component} next run at {Next:o} ({Cron})",
                    component.Name, next.Value.ToLocalTime(), component.Cron);

                var delay = next.Value - now;
                if (delay > TimeSpan.Zero)
                {
                    await Task.Delay(delay, timeProvider, stoppingToken).ConfigureAwait(false);
                }

                await TriggerAsync(component.Name, "cron tick", stoppingToken).ConfigureAwait(false);
            }
        }
        catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
        {
            // Host shutdown.
        }
    }

    private async Task WatchQuietlyAsync(CancellationToken stoppingToken)
    {
        try
        {
            await lifecycle.WatchAsync(stoppingToken).ConfigureAwait(false);
        }
        catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
        {
            // Host shutdown.
        }
    }
}

