namespace Intropy.Topology.Aspire;

/// <summary>
/// Stages the effective Dapr resource set for one integration. Local resources are copied first;
/// generated resources replace only an identical <c>(apiVersion, kind, metadata.name)</c> identity.
/// A generated HTTP endpoint is staged only for a component named in its scopes.
/// </summary>
internal static class ComponentOverlay
{
    /// <summary>Stages the component set and returns the staged directory.</summary>
    public static string Stage(string appHostDirectory, string componentName, string generatedComponentsDir)
    {
        var stagedDir = Path.Combine(appHostDirectory, "obj", "dapr-components", componentName);
        if (Directory.Exists(stagedDir))
        {
            Directory.Delete(stagedDir, recursive: true);
        }

        Directory.CreateDirectory(stagedDir);
        var stagedByName = new Dictionary<string, StagedResource>(StringComparer.Ordinal);
        CopyResources(ProjectConvention.LocalComponentsDir(appHostDirectory, componentName), stagedDir, stagedByName, componentName, generated: false);
        CopyResources(generatedComponentsDir, stagedDir, stagedByName, componentName, generated: true);
        return stagedDir;
    }

    /// <summary>The top-level <c>metadata.name</c> of a single-document Dapr resource YAML.</summary>
    internal static string? MetadataName(string yaml) => Parse(yaml, "resource")?.Identity.Name;

    private static void CopyResources(
        string sourceDirectory,
        string stagedDirectory,
        Dictionary<string, StagedResource> stagedByName,
        string componentName,
        bool generated)
    {
        foreach (var file in ComponentFiles(sourceDirectory))
        {
            var yaml = File.ReadAllText(file);
            var resource = Parse(yaml, file) ?? throw new InvalidOperationException($"Dapr resource '{file}' has no metadata.name.");
            if (generated && resource.IsHttpEndpoint && !resource.Scopes.Contains(componentName, StringComparer.Ordinal))
            {
                continue;
            }

            if (stagedByName.TryGetValue(resource.Identity.Name, out var existing))
            {
                if (existing.IsGenerated == generated
                    || existing.Identity.ApiVersion != resource.Identity.ApiVersion
                    || existing.Identity.Kind != resource.Identity.Kind
                    || existing.Identity.Name != resource.Identity.Name)
                {
                    throw new InvalidOperationException(
                        $"Dapr resource '{file}' conflicts with an existing resource named '{resource.Identity.Name}'; replacement requires a unique matching apiVersion, kind, and metadata.name.");
                }

                var prior = Path.Combine(stagedDirectory, existing.Identity.FileName);
                File.Delete(prior);
            }

            var targetName = Path.GetFileName(file);
            var target = Path.Combine(stagedDirectory, targetName);
            File.Copy(file, target, overwrite: true);
            stagedByName[resource.Identity.Name] = new StagedResource(resource.Identity with { FileName = targetName }, generated);
        }
    }

    private static Resource? Parse(string yaml, string source)
    {
        if (yaml.Split("---", StringSplitOptions.None).Length > 1)
        {
            throw new InvalidOperationException($"Dapr resource '{source}' contains multiple YAML documents.");
        }

        string? apiVersion = null;
        string? kind = null;
        string? name = null;
        var scopes = new List<string>();
        var inMetadata = false;
        var inScopes = false;
        foreach (var raw in yaml.Split('\n'))
        {
            var line = raw.TrimEnd();
            if (line.StartsWith("apiVersion:", StringComparison.Ordinal)) apiVersion = Value(line);
            if (line.StartsWith("kind:", StringComparison.Ordinal)) kind = Value(line);
            if (line == "metadata:") { inMetadata = true; inScopes = false; continue; }
            if (line == "scopes:") { inScopes = true; inMetadata = false; continue; }
            if (inMetadata && raw.StartsWith(' ') && line.TrimStart().StartsWith("name:", StringComparison.Ordinal)) name = Value(line.TrimStart());
            if (inScopes && line.TrimStart().StartsWith("- ", StringComparison.Ordinal)) scopes.Add(Value(line.TrimStart()[2..]));
            if (!raw.StartsWith(' ') && !line.TrimStart().StartsWith("- ", StringComparison.Ordinal)
                && line.Length > 0 && line is not "metadata:" and not "scopes:") { inMetadata = false; inScopes = false; }
        }

        return name is null || apiVersion is null || kind is null
            ? null
            : new Resource(new ResourceIdentity(apiVersion, kind, name, Path.GetFileName(source)), scopes);
    }

    private static string Value(string line) => line[(line.IndexOf(':', StringComparison.Ordinal) + 1)..].Trim().Trim('"', '\'');

    private static IEnumerable<string> ComponentFiles(string directory) =>
        Directory.Exists(directory)
            ? Directory.EnumerateFiles(directory)
                .Where(file => file.EndsWith(".yaml", StringComparison.OrdinalIgnoreCase) || file.EndsWith(".yml", StringComparison.OrdinalIgnoreCase))
                .OrderBy(file => file, StringComparer.Ordinal)
            : [];

    private sealed record StagedResource(ResourceIdentity Identity, bool IsGenerated);

    private sealed record Resource(ResourceIdentity Identity, IReadOnlyList<string> Scopes)
    {
        public bool IsHttpEndpoint => Identity.Kind == "HTTPEndpoint";
    }

    private sealed record ResourceIdentity(string ApiVersion, string Kind, string Name, string FileName);
}

        try
        {
            using var listener = new TcpListener(IPAddress.Loopback, port);
            listener.Start();
        }
        catch (SocketException ex)
        {
            throw new InvalidOperationException(
                $"{backend} requires host port {port}, but it is already in use. Stop the conflicting process and retry.", ex);
        }
    }

    private static void WithTcpReadiness(
        IDistributedApplicationBuilder builder,
        IResourceBuilder<ContainerResource> container,
        TcpReadyHealthCheck readiness)
    {
        var key = $"{container.Resource.Name}-tcp-ready";
        builder.Services.AddHealthChecks().AddCheck(key, readiness);
        container.WithHealthCheck(key);
    }

    private static void Wire(
        IResourceBuilder<ProjectResource> project,
        ComponentModel component,
        string resourcesPath,
        string configDir,
        IResourceBuilder<ContainerResource> redis,
        IResourceBuilder<ContainerResource>? microcks)
    {
        project
            .WithDaprSidecar(sidecar =>
            {
                sidecar.WithOptions(new DaprSidecarOptions
                {
                    AppId = component.Name,
                    ResourcesPaths = [resourcesPath],
                });
                sidecar.WaitFor(redis);
            })
            .WithEnvironment("INTROPY__COMPONENT", component.Name)
            .WithEnvironment("INTROPY__CONFIG", Path.Combine(configDir, $"{component.Name}.intropy.json"))
            .WaitFor(redis);
        if (microcks is not null && component.Uses.Count > 0)
        {
            project.WaitFor(microcks);
        }
    }
}

namespace Intropy.Topology.Validation.Rules;

/// <summary>
/// A component must not publish more than one topic. Every <c>Publishes</c> call
/// records the single <c>default</c> output port; multi-output components (named ports)
/// are not part of the minimal model.
/// </summary>
internal sealed class DuplicatePortRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        foreach (var component in context.Builder.Components)
        {
            if (component.PublishCalls.Count > 1)
            {
                yield return new TopologyDiagnostic(
                    DiagnosticSeverity.Error,
                    $"The component declares {component.PublishCalls.Count} Publishes calls; a component publishes exactly one topic.",
                    component.Name);
            }
        }
    }
}

/// <summary>A component must not subscribe to the same topic more than once.</summary>
internal sealed class DuplicateSubscriptionRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        foreach (var component in context.Builder.Components)
        {
            var duplicates = component.SubscribeCalls
                .GroupBy(t => (t.PubSubName, t.TopicName))
                .Where(g => g.Count() > 1);

            foreach (var group in duplicates)
            {
                yield return new TopologyDiagnostic(
                    DiagnosticSeverity.Error,
                    $"The topic '{group.Key.TopicName}' on pubsub '{group.Key.PubSubName}' is subscribed to more than once by the same component.",
                    component.Name);
            }
        }
    }
}

/// <summary>One topic must not be used with two different event contract types.</summary>
internal sealed class TopicContractConflictRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        var usages = context.Builder.Components.SelectMany(TopicUsages);

        var conflicts = usages
            .GroupBy(t => (t.PubSubName, t.TopicName))
            .Where(g => g.Select(t => t.ContractType).Distinct().Count() > 1);

        foreach (var group in conflicts)
        {
            var contracts = string.Join(
                ", ",
                group.Select(t => t.ContractType.FullName ?? t.ContractType.Name).Distinct().Order(StringComparer.Ordinal));
            yield return new TopologyDiagnostic(
                DiagnosticSeverity.Error,
                $"The topic '{group.Key.TopicName}' on pubsub '{group.Key.PubSubName}' is declared with conflicting contract types: {contracts}.",
                group.Key.TopicName);
        }
    }

    private static IEnumerable<TopicRef> TopicUsages(Component component)
    {
        foreach (var (_, topic) in component.PublishCalls)
        {
            yield return topic;
        }

        foreach (var topic in component.SubscribeCalls)
        {
            yield return topic;
        }
    }
}

/// <summary>One connector name must not be declared with two different transports.</summary>
internal sealed class ConnectorConflictRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        var usages = context.Builder.Components.SelectMany(ConnectorUsages);

        foreach (var group in usages.GroupBy(c => c.Name, StringComparer.Ordinal))
        {
            var transports = group
                .Select(c => c.Transport)
                .Distinct()
                .ToArray();
            if (transports.Length > 1)
            {
                var transportTypes = transports
                    .Select(t => t.DaprType)
                    .Distinct(StringComparer.Ordinal)
                    .Order(StringComparer.Ordinal);
                yield return new TopologyDiagnostic(
                    DiagnosticSeverity.Error,
                    $"The connector '{group.Key}' is declared with conflicting transports: {string.Join(", ", transportTypes)}.",
                    group.Key);
            }
        }
    }

    private static IEnumerable<ConnectorRef> ConnectorUsages(Component component)
    {
        foreach (var (connector, _) in component.ConnectorCalls)
        {
            yield return connector;
        }
    }
}

/// <summary>
/// A connector's declared transport must support every direction the connector is used in.
/// </summary>
internal sealed class ConnectorTransportCapabilityRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        foreach (var component in context.Builder.Components)
        {
            foreach (var (connector, direction) in component.ConnectorCalls)
            {
                var transport = connector.Transport;
                if (Supports(direction, transport))
                {
                    continue;
                }

                var operation = direction == Intropy.Topology.Model.ConnectorDirection.In ? "From" : "To";
                var capability = direction == Intropy.Topology.Model.ConnectorDirection.In ? "input" : "output";
                yield return new TopologyDiagnostic(
                    DiagnosticSeverity.Error,
                    $"The connector '{connector.Name}' declares transport '{transport.DaprType}', which does not support {capability} required by {operation}.",
                    component.Name);
            }
        }
    }

    private static bool Supports(Intropy.Topology.Model.ConnectorDirection direction, Transport transport) =>
        direction == Intropy.Topology.Model.ConnectorDirection.In ? transport.SupportsInput : transport.SupportsOutput;
}

/// <summary>
/// A connector should not keep the placeholder <see cref="Transport.Default"/> transport.
/// The default compiles and passes capability checks so a freshly scaffolded system builds
/// and runs locally — the placeholder must not block F5 — but it must be replaced before
/// deployment, so the rule warns. Deployment generation is where it becomes an error.
/// </summary>
internal sealed class ConnectorDefaultTransportRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        foreach (var component in context.Builder.Components)
        {
            foreach (var (connector, _) in component.ConnectorCalls)
            {
                if (connector.Transport is DefaultTransport)
                {
                    yield return new TopologyDiagnostic(
                        DiagnosticSeverity.Warning,
                        $"The connector '{connector.Name}' still uses the placeholder default transport — replace it with a concrete transport (e.g. Transport.Sftp()) before deployment.",
                        connector.Name);
                }
            }
        }
    }
}

using Intropy.Topology.Model;

namespace Intropy.Topology.Building;

/// <summary>
/// Folds the builder declarations into the immutable model: components in declaration
/// order, resources deduplicated from usage and sorted for determinism. Materialization
/// never fails — structurally broken declarations still materialize (first-seen wins on
/// conflicts) so validation rules can inspect and report the full picture.
/// </summary>
internal static class TopologyMaterializer
{
    public static SystemTopology Materialize(SystemBuilder builder)
    {
        var components = new List<ComponentModel>();
        var topics = new Dictionary<(string PubSub, string Topic), TopicAccumulator>();
        var connectors = new Dictionary<string, ConnectorAccumulator>();
        var services = new Dictionary<string, ServiceAccumulator>(StringComparer.Ordinal);

        foreach (var component in builder.Components)
        {
            components.Add(MaterializeComponent(component, topics, connectors, services));
        }

        return new SystemTopology
        {
            SystemName = builder.SystemName,
            Components = components,
            Topics = topics
                .OrderBy(t => t.Key.PubSub, StringComparer.Ordinal)
                .ThenBy(t => t.Key.Topic, StringComparer.Ordinal)
                .Select(t => new TopicResource
                {
                    PubSubName = t.Key.PubSub,
                    TopicName = t.Key.Topic,
                    ContractTypeName = t.Value.ContractTypeName,
                    Publishers = [.. t.Value.Publishers],
                    Subscribers = [.. t.Value.Subscribers],
                })
                .ToArray(),
            Connectors = connectors
                .OrderBy(c => c.Key, StringComparer.Ordinal)
                .Select(c => new ConnectorResource
                {
                    Name = c.Key,
                    Transport = c.Value.Transport,
                    Directions = [.. c.Value.Directions.Order()],
                    UsedBy = [.. c.Value.UsedBy],
                })
                .ToArray(),
            Services = services
                .OrderBy(s => s.Key, StringComparer.Ordinal)
                .Select(s => new ServiceResource { AppId = s.Key, Consumers = [.. s.Value.Consumers] })
                .ToArray(),
        };
    }

    private static ComponentModel MaterializeComponent(
        Component component,
        Dictionary<(string PubSub, string Topic), TopicAccumulator> topics,
        Dictionary<string, ConnectorAccumulator> connectors,
        Dictionary<string, ServiceAccumulator> services)
    {
        var subscribes = new List<TopicSubscription>();
        foreach (var topic in component.SubscribeCalls)
        {
            subscribes.Add(new TopicSubscription
            {
                PubSubName = topic.PubSubName,
                TopicName = topic.TopicName,
            });
            AccumulateTopic(topics, topic).Subscribers.Add(component.Name);
        }

        var publishes = new List<PublishEdge>();
        foreach (var (port, topic) in component.PublishCalls)
        {
            publishes.Add(new PublishEdge
            {
                Port = port,
                PubSubName = topic.PubSubName,
                TopicName = topic.TopicName,
            });
            AccumulateTopic(topics, topic).Publishers.Add(component.Name);
        }

        var connectorEdges = new List<ConnectorEdge>();
        var seenConnectorEdges = new HashSet<(string, ConnectorDirection)>();
        foreach (var (connector, direction) in component.ConnectorCalls)
        {
            AccumulateConnector(connectors, connector, direction).UsedBy.Add(component.Name);
            if (seenConnectorEdges.Add((connector.Name, direction)))
            {
                connectorEdges.Add(new ConnectorEdge { ConnectorName = connector.Name, Direction = direction });
            }
        }

        var serviceAppIds = new List<string>();
        var seenServices = new HashSet<string>(StringComparer.Ordinal);
        foreach (var service in component.ServiceCalls)
        {
            if (!services.TryGetValue(service.AppId, out var accumulator))
            {
                services[service.AppId] = accumulator = new ServiceAccumulator();
            }

            accumulator.Consumers.Add(component.Name);
            if (seenServices.Add(service.AppId))
            {
                serviceAppIds.Add(service.AppId);
            }
        }

        return new ComponentModel
        {
            Name = component.Name,
            Kind = component.Kind,
            Schedule = component.ScheduleCall,
            Subscribes = subscribes,
            Publishes = publishes,
            Connectors = connectorEdges,
            Uses = serviceAppIds,
        };
    }

    private static TopicAccumulator AccumulateTopic(
        Dictionary<(string PubSub, string Topic), TopicAccumulator> topics,
        TopicRef topic)
    {
        var key = (topic.PubSubName, topic.TopicName);
        if (!topics.TryGetValue(key, out var accumulator))
        {
            accumulator = new TopicAccumulator(topic.ContractType.FullName ?? topic.ContractType.Name);
            topics[key] = accumulator;
        }

        return accumulator;
    }

    private static ConnectorAccumulator AccumulateConnector(
        Dictionary<string, ConnectorAccumulator> connectors,
        ConnectorRef connector,
        ConnectorDirection direction)
    {
        if (!connectors.TryGetValue(connector.Name, out var accumulator))
        {
            // First-seen wins on identity; conflicting declarations are reported by validation.
            accumulator = new ConnectorAccumulator(connector.Transport);
            connectors[connector.Name] = accumulator;
        }

        accumulator.Directions.Add(direction);
        return accumulator;
    }

    private sealed class TopicAccumulator(string contractTypeName)
    {
        public string ContractTypeName { get; } = contractTypeName;
        public SortedSet<string> Publishers { get; } = new(StringComparer.Ordinal);
        public SortedSet<string> Subscribers { get; } = new(StringComparer.Ordinal);
    }

    private sealed class ServiceAccumulator
    {
        public SortedSet<string> Consumers { get; } = new(StringComparer.Ordinal);
    }

    private sealed class ConnectorAccumulator(Transport transport)
    {
        public Transport Transport { get; } = transport;
        public HashSet<ConnectorDirection> Directions { get; } = [];
        public SortedSet<string> UsedBy { get; } = new(StringComparer.Ordinal);
    }
}

using Intropy.Topology.Model;

namespace Intropy.Topology.Validation;

/// <summary>Runs every topology rule and collects the diagnostics.</summary>
internal static class TopologyRules
{
    private static readonly ITopologyRule[] Rules =
    [
        new Rules.DuplicateComponentNameRule(),
        new Rules.EmptySystemRule(),
        new Rules.DuplicatePortRule(),
        new Rules.DuplicateSubscriptionRule(),
        new Rules.TopicContractConflictRule(),
        new Rules.ConnectorConflictRule(),
        new Rules.ConnectorTransportCapabilityRule(),
        new Rules.ConnectorDefaultTransportRule(),
        new Rules.MissingRequiredOutputRule(),
        new Rules.MissingRequiredSubscriptionRule(),
        new Rules.ScheduleExpressionRule(),
        new Rules.UnconsumedTopicRule(),
        new Rules.UnproducedTopicRule(),
        new Rules.NoEdgesRule(),
        new Rules.PubSubConnectorNameCollisionRule(),
        new Rules.ServiceUsageRule(),
    ];

    public static IReadOnlyList<TopologyDiagnostic> Run(SystemBuilder builder, SystemTopology topology)
    {
        var context = new ValidationContext(builder, topology);
        return Rules.SelectMany(rule => rule.Evaluate(context)).ToArray();
    }
}

using System.Reflection;
using System.Text.Json;
using System.Text.Json.Serialization;
using Intropy.Topology;
using Intropy.Topology.Model;

namespace Intropy.Topology.Generation;

/// <summary>
/// The non-Aspire backend: the <c>check</c>, <c>graph</c>, and <c>generate</c> CLI verbs over a
/// discovered system. F5 (the Aspire backend) and these verbs consume the same discovered truth.
/// </summary>
public static class IntropyGenerate
{
    private static readonly JsonSerializerOptions s_json = new()
    {
        WriteIndented = true,
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
    };

    /// <summary>Runs a generation CLI verb against the system discovered in <paramref name="assembly"/>.</summary>
    /// <param name="assembly">The assembly declaring the <see cref="ISystemDefinition"/>.</param>
    /// <param name="args">Command-line arguments; <c>args[0]</c> is the verb (check | graph | generate).</param>
    /// <returns>A process exit code.</returns>
    public static Task<int> RunAsync(Assembly assembly, string[] args)
    {
        ArgumentNullException.ThrowIfNull(assembly);
        ArgumentNullException.ThrowIfNull(args);

        var verb = args.Length > 0 ? args[0] : "check";
        return Task.FromResult(verb switch
        {
            "check" => Check(assembly),
            "graph" => Graph(assembly, args),
            "generate" => Generate(assembly, args),
            _ => Unknown(verb),
        });
    }

    private static int Check(Assembly assembly)
    {
        try
        {
            var discovered = SystemDiscovery.Discover(assembly);
            DevelopmentDiscovery.Discover(assembly, discovered.Topology, Directory.GetCurrentDirectory());
            Console.WriteLine($"ok: '{discovered.Topology.SystemName}' is valid ({discovered.Topology.Components.Count} components).");
            return 0;
        }
        catch (Exception ex) when (ex is TopologyValidationException or DevelopmentValidationException or InvalidOperationException)
        {
            Console.Error.WriteLine($"error: {ex.Message}");
            return 1;
        }
    }

    private static int Graph(Assembly assembly, string[] args)
    {
        try
        {
            // Tolerant discovery: a partially built system (placeholder transports, one-sided
            // topics) must still be inspectable. Warnings go to stderr so stdout stays pure JSON.
            var topology = SystemDiscovery.DiscoverTolerant(assembly, out var diagnostics).Topology;
            foreach (var diagnostic in diagnostics)
            {
                var severity = diagnostic.Severity == DiagnosticSeverity.Warning ? "warning" : "error";
                Console.Error.WriteLine($"{severity}: {diagnostic.Message}");
            }

            var development = args.Contains("--development", StringComparer.Ordinal)
                ? DevelopmentDiscovery.Discover(assembly, topology, Directory.GetCurrentDirectory())
                : null;
            Console.WriteLine(JsonSerializer.Serialize(GraphDocument.From(topology, development), s_json));
            return 0;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"error: {ex.Message}");
            return 1;
        }
    }

    /// <summary>Maps the validated internal model to the topology.intropy.io/v1 interchange contract.</summary>
    private sealed record GraphDocument(
        string ApiVersion,
        string Kind,
        string System,
        IReadOnlyList<GraphComponent>? Components,
        IReadOnlyList<GraphTopic>? Topics,
        IReadOnlyList<GraphConnector>? Connectors,
        IReadOnlyList<GraphService>? Services,
        GraphDevelopment? Development)
    {
        public static GraphDocument From(SystemTopology topology, DevelopmentManifest? development) => new(
            "topology.intropy.io/v1",
            "SystemTopology",
            topology.SystemName,
            Optional(topology.Components.Select(GraphComponent.From)),
            Optional(topology.Topics.Select(GraphTopic.From)),
            Optional(topology.Connectors.Select(GraphConnector.From)),
            Optional(topology.Services.Select(GraphService.From)),
            development is null ? null : GraphDevelopment.From(development));
    }

    private sealed record GraphDevelopment(
        IReadOnlyList<GraphMock>? Mocks,
        IReadOnlyList<GraphFileConnector>? Files)
    {
        public static GraphDevelopment From(DevelopmentManifest development) => new(
            Optional(development.Mocks.Select(GraphMock.From)),
            Optional(development.Files.Select(GraphFileConnector.From)));
    }

    private sealed record GraphMock(string AppId, string Artifact, string Title, string Version, string BaseUri)
    {
        public static GraphMock From(OpenApiMock mock) => new(
            mock.AppId, mock.ArtifactPath, mock.Title, mock.Version, mock.BaseUri.AbsoluteUri);
    }

    private sealed record GraphFileConnector(string Connector, string RootPath)
    {
        public static GraphFileConnector From(ConnectorFileResolution file) => new(file.ConnectorName, file.RootPath);
    }

    private sealed record GraphComponent(
        string Name,
        string Kind,
        IReadOnlyList<GraphTopicReference>? Subscribes,
        IReadOnlyList<GraphPublication>? Publishes,
        IReadOnlyList<GraphConnectorUse>? Connectors,
        IReadOnlyList<string>? Uses)
    {
        public static GraphComponent From(ComponentModel component) => new(
            component.Name,
            KebabCase(component.Kind.ToString()),
            Optional(component.Subscribes.Select(t => new GraphTopicReference(t.PubSubName, t.TopicName))),
            Optional(component.Publishes.Select(p => new GraphPublication(
                p.Port == "default" ? null : p.Port, p.PubSubName, p.TopicName))),
            Optional(component.Connectors.Select(c => new GraphConnectorUse(
                c.ConnectorName, Direction(c.Direction)))),
            Optional(component.Uses));
    }

    private sealed record GraphTopicReference(
        [property: JsonPropertyName("pubsub")] string PubSub,
        string Topic);

    private sealed record GraphPublication(
        string? Port,
        [property: JsonPropertyName("pubsub")] string PubSub,
        string Topic);

    private sealed record GraphConnectorUse(string Connector, string Direction);

    private sealed record GraphTopic(
        [property: JsonPropertyName("pubsub")] string PubSub,
        string Topic,
        string Contract,
        IReadOnlyList<string>? Publishers,
        IReadOnlyList<string>? Subscribers)
    {
        public static GraphTopic From(TopicResource topic) => new(
            topic.PubSubName,
            topic.TopicName,
            topic.ContractTypeName,
            Optional(topic.Publishers),
            Optional(topic.Subscribers));
    }

    private sealed record GraphConnector(
        string Name,
        GraphTransport Transport,
        IReadOnlyList<string>? Directions,
        IReadOnlyList<string>? UsedBy)
    {
        public static GraphConnector From(ConnectorResource connector) => new(
            connector.Name,
            GraphTransport.From(connector.Transport),
            Optional(connector.Directions.Select(Direction)),
            Optional(connector.UsedBy));
    }

    private sealed record GraphService(string AppId, IReadOnlyList<string>? Consumers)
    {
        public static GraphService From(ServiceResource service) => new(service.AppId, Optional(service.Consumers));
    }

    private sealed record GraphTransport(string Type, bool SupportsInput, bool SupportsOutput)
    {
        public static GraphTransport From(Transport transport) => transport switch
        {
            SftpTransport => new("sftp", transport.SupportsInput, transport.SupportsOutput),
            DefaultTransport => new("default", transport.SupportsInput, transport.SupportsOutput),
            _ => throw new InvalidOperationException($"Unsupported graph transport '{transport.GetType().Name}'."),
        };
    }

    private static T[]? Optional<T>(IEnumerable<T> values)
    {
        var array = values.ToArray();
        return array.Length > 0 ? array : null;
    }

    private static string Direction(ConnectorDirection direction) =>
        direction == ConnectorDirection.In ? "in" : "out";

    private static string KebabCase(string pascal)
    {
        var builder = new System.Text.StringBuilder(pascal.Length + 4);
        foreach (var c in pascal)
        {
            if (char.IsUpper(c) && builder.Length > 0)
            {
                builder.Append('-');
            }

            builder.Append(char.ToLowerInvariant(c));
        }

        return builder.ToString();
    }

    private static int Generate(Assembly assembly, string[] args)
    {
        try
        {
            var directory = args.Skip(1).FirstOrDefault(a => !a.StartsWith('-')) ?? "./out";
            var discovered = SystemDiscovery.Discover(assembly);
            var development = DevelopmentDiscovery.Discover(assembly, discovered.Topology, Directory.GetCurrentDirectory());
            var artifacts = TopologyGenerator.Generate(discovered.Topology, development);
            artifacts.WriteTo(directory);

            Console.WriteLine($"generated {artifacts.Files.Count} files to '{directory}':");
            foreach (var file in artifacts.Files)
            {
                Console.WriteLine($"  {file.RelativePath}");
            }

            return 0;
        }
        catch (Exception ex) when (ex is TopologyValidationException or DevelopmentValidationException or InvalidOperationException)
        {
            Console.Error.WriteLine($"error: {ex.Message}");
            return 1;
        }
    }

    private static int Unknown(string verb)
    {
        Console.Error.WriteLine($"unknown command '{verb}'. Expected: check | graph | generate.");
        return 2;
    }
}

