namespace Intropy.Topology.Test.Refs;

public class ConnectorRefTests
{
    [Fact]
    public void Define_WithValidName_ShouldExposeProperties()
    {
        // Act
        var connector = ConnectorRef.Define("pim", Transport.Sftp());

        // Assert
        Assert.Equal("pim", connector.Name);
        Assert.Equal(Transport.Sftp(), connector.Transport);
    }

    [Theory]
    [InlineData("Pim")]
    [InlineData("binding.pim")]
    [InlineData("-pim")]
    [InlineData("")]
    public void REDACTED(string name)
    {
        // Act & Assert: Define carries [ConstantExpected] (CA1857 fires on this non-constant
        // argument, proving the attribute works); suppressed here to test the runtime guard.
#pragma warning disable CA1857
        Assert.Throws<ArgumentException>(() => ConnectorRef.Define(name, Transport.Sftp()));
#pragma warning restore CA1857
    }

    [Fact]
    public void Define_WithNullTransport_ShouldThrowArgumentNullException()
    {
        // Act & Assert
        Assert.Throws<ArgumentNullException>(() => ConnectorRef.Define("pim", null!));
    }

    [Fact]
    public void Equals_WithSameNameAndTransport_ShouldBeEqual()
    {
        // Arrange
        var first = ConnectorRef.Define("pim", Transport.Sftp());
        var second = ConnectorRef.Define("pim", Transport.Sftp());

        // Assert
        Assert.Equal(first, second);
    }
}

public class TransportTests
{
    [Fact]
    public void Sftp_ShouldExposeDaprTypeAndCapabilities()
    {
        // Act
        var transport = Transport.Sftp();

        // Assert
        Assert.IsType<SftpTransport>(transport);
        Assert.Equal("bindings.sftp", transport.DaprType);
        Assert.True(transport.SupportsInput);
        Assert.True(transport.SupportsOutput);
    }

    [Fact]
    public void Sftp_ShouldRoundTripThroughTransportPolymorphicSerialization()
    {
        // Act
        var json = System.Text.Json.JsonSerializer.Serialize<Transport>(Transport.Sftp());
        var transport = System.Text.Json.JsonSerializer.Deserialize<Transport>(json);

        // Assert
        Assert.Equal("{\"$transport\":\"sftp\",\"DaprType\":\"bindings.sftp\"}", json);
        Assert.Equal(Transport.Sftp(), transport);
    }

    [Fact]
    public void Default_ShouldExposeEmptyDaprTypeBothCapabilities()
    {
        // Act
        var transport = Transport.Default();

        // Assert
        Assert.IsType<DefaultTransport>(transport);
        Assert.Equal("", transport.DaprType);
        Assert.True(transport.SupportsInput);
        Assert.True(transport.SupportsOutput);
    }

    [Fact]
    public void Default_ShouldRoundTripThroughTransportPolymorphicSerialization()
    {
        // Arrange
        var expected = Transport.Default();

        // Act
        var json = System.Text.Json.JsonSerializer.Serialize<Transport>(expected);
        var transport = System.Text.Json.JsonSerializer.Deserialize<Transport>(json);

        // Assert
        Assert.Equal("{\"$transport\":\"default\",\"DaprType\":\"\"}", json);
        Assert.Equal(expected, transport);
    }

}

public class TopicRefTests
{
    [Fact]
    public void Define_WithValidNames_ShouldExposeProperties()
    {
        // Act
        var topic = TopicRef<RawEvent>.Define("test-pubsub", "raw-events");

        // Assert
        Assert.Equal("test-pubsub", topic.PubSubName);
        Assert.Equal("raw-events", topic.TopicName);
        Assert.Equal(typeof(RawEvent), topic.ContractType);
    }

    [Theory]
    [InlineData("Bad-PubSub", "topic")]
    [InlineData("pubsub", "Bad-Topic")]
    [InlineData("pubsub", "")]
    [InlineData("", "topic")]
    [InlineData("pub sub", "topic")]
    public void REDACTED(string pubSubName, string topicName)
    {
        // Act & Assert: [ConstantExpected] suppressed to test the runtime guard
#pragma warning disable CA1857
        Assert.Throws<ArgumentException>(() => TopicRef<RawEvent>.Define(pubSubName, topicName));
#pragma warning restore CA1857
    }

    [Fact]
    public void REDACTED()
    {
        // Arrange
        var longName = string.Join('.', Enumerable.Repeat("abcdefghij", 26));

        // Act & Assert: [ConstantExpected] suppressed to test the runtime guard
#pragma warning disable CA1857
        Assert.Throws<ArgumentException>(() => TopicRef<RawEvent>.Define("pubsub", longName));
#pragma warning restore CA1857
    }

    [Fact]
    public void Equals_WithSameNamesAndContract_ShouldBeEqual()
    {
        // Arrange
        var first = TopicRef<RawEvent>.Define("test-pubsub", "raw-events");
        var second = TopicRef<RawEvent>.Define("test-pubsub", "raw-events");

        // Assert
        Assert.Equal(first, second);
    }

    [Fact]
    public void Equals_WithSameNamesButDifferentContract_ShouldNotBeEqual()
    {
        // Arrange
        TopicRef first = TopicRef<RawEvent>.Define("test-pubsub", "raw-events");
        TopicRef second = TopicRef<EnrichedEvent>.Define("test-pubsub", "raw-events");

        // Assert
        Assert.NotEqual(first, second);
    }
}

using System.Text.Json;
using Intropy.Topology.Model;

namespace Intropy.Topology.Test.Building;

/// <summary>
/// The living spec: mirrors the SystemHost sample from the README and asserts the full
/// shape of the materialized model.
/// </summary>
public class EndToEndTests
{
    private static class ProductFlow
    {
        public static readonly TopicRef<RawEvent> Raw =
            TopicRef<RawEvent>.Define("product-distribution-pubsub", "product-raw");
    }

    private static class PriceFlow
    {
        public static readonly TopicRef<RawEvent> Raw =
            TopicRef<RawEvent>.Define("product-distribution-pubsub", "price-raw");
    }

    private static readonly ConnectorRef s_pim = ConnectorRef.Define("pim", Transport.Sftp());
    private static readonly ConnectorRef s_erp = ConnectorRef.Define("erp", Transport.Sftp());

    private static SystemBuilder DeclareSystem()
    {
        var s = SystemBuilder.Create("product-distribution");

        s.AddExtractor("pim-extractor")
            .From(s_pim)
            .Publishes(ProductFlow.Raw)
            .WithSchedule("*/5 * * * *");

        s.AddTransactionalIntegration("pricing-service")
            .From(s_pim)
            .To(s_erp);

        s.AddLoader("product-loader")
            .Subscribes(ProductFlow.Raw)
            .To(s_erp);

        // An extractor whose source stays a private local component: no From edge.
        s.AddExtractor("price-extractor")
            .Publishes(PriceFlow.Raw);

        // A loader whose destination stays a private local component: no To edge.
        s.AddLoader("price-loader")
            .Subscribes(PriceFlow.Raw);

        return s;
    }

    [Fact]
    public void Build_WithSampleSystem_ShouldMaterializeFullTopology()
    {
        // Act
        var topology = DeclareSystem().Build();

        // Assert: system + components
        Assert.Equal("product-distribution", topology.SystemName);
        Assert.Equal(["pim-extractor", "pricing-service", "product-loader", "price-extractor", "price-loader"],
            topology.Components.Select(w => w.Name));

        var extractor = topology.Components[0];
        Assert.Equal(ConnectorDirection.In, Assert.Single(extractor.Connectors).Direction);
        Assert.Equal("default", Assert.Single(extractor.Publishes).Port);
        Assert.Equal("*/5 * * * *", extractor.Schedule);

        var pricing = topology.Components[1];
        Assert.Null(pricing.Schedule);
        Assert.Equal(
            [("pim", ConnectorDirection.In), ("erp", ConnectorDirection.Out)],
            pricing.Connectors.Select(c => (c.ConnectorName, c.Direction)));

        var loader = topology.Components[2];
        Assert.Equal("product-raw", Assert.Single(loader.Subscribes).TopicName);
        Assert.Equal(("erp", ConnectorDirection.Out),
            (Assert.Single(loader.Connectors).ConnectorName, Assert.Single(loader.Connectors).Direction));

        // Assert: materialized resources
        Assert.Equal(["price-raw", "product-raw"], topology.Topics.Select(t => t.TopicName));
        var raw = topology.Topics.Single(t => t.TopicName == "product-raw");
        Assert.Equal(["pim-extractor"], raw.Publishers);
        Assert.Equal(["product-loader"], raw.Subscribers);
        var priceRaw = topology.Topics.Single(t => t.TopicName == "price-raw");
        Assert.Equal(["price-extractor"], priceRaw.Publishers);
        Assert.Equal(["price-loader"], priceRaw.Subscribers);

        Assert.Equal(["erp", "pim"], topology.Connectors.Select(c => c.Name));
        var erp = topology.Connectors[0];
        Assert.Equal(Transport.Sftp(), erp.Transport);
        Assert.Equal("binding.erp", erp.DaprComponentName);
        Assert.Equal(["pricing-service", "product-loader"], erp.UsedBy);
        var pim = topology.Connectors[1];
        Assert.Equal(Transport.Sftp(), pim.Transport);
        Assert.Equal("binding.pim", pim.DaprComponentName);
        Assert.Equal(["pim-extractor", "pricing-service"], pim.UsedBy);
    }

    [Fact]
    public void Validate_WithSampleSystem_ShouldReportNothing()
    {
        // Act & Assert
        Assert.Empty(DeclareSystem().Validate());
    }

    [Fact]
    public void Serialize_WithSampleSystem_ShouldMatchSnapshot()
    {
        // Byte-exact snapshot of the sample system's serialized model: guards materializer
        // output against unintentional change. Regenerate only on intentional model changes.
        const string expected =
            """{"SystemName":"product-distribution","Components":[{"Name":"pim-extractor","Kind":0,"Schedule":"*/5 * * * *","Subscribes":[],"Publishes":[{"Port":"default","PubSubName":"product-distribution-pubsub","TopicName":"product-raw"}],"Connectors":[{"ConnectorName":"pim","Direction":0}],"Uses":[]},{"Name":"pricing-service","Kind":2,"Schedule":null,"Subscribes":[],"Publishes":[],"Connectors":[{"ConnectorName":"pim","Direction":0},{"ConnectorName":"erp","Direction":1}],"Uses":[]},{"Name":"product-loader","Kind":1,"Schedule":null,"Subscribes":[{"PubSubName":"product-distribution-pubsub","TopicName":"product-raw"}],"Publishes":[],"Connectors":[{"ConnectorName":"erp","Direction":1}],"Uses":[]},{"Name":"price-extractor","Kind":0,"Schedule":null,"Subscribes":[],"Publishes":[{"Port":"default","PubSubName":"product-distribution-pubsub","TopicName":"price-raw"}],"Connectors":[],"Uses":[]},{"Name":"price-loader","Kind":1,"Schedule":null,"Subscribes":[{"PubSubName":"product-distribution-pubsub","TopicName":"price-raw"}],"Publishes":[],"Connectors":[],"Uses":[]}],"Topics":[{"PubSubName":"product-distribution-pubsub","TopicName":"price-raw","ContractTypeName":"Intropy.Topology.Test.RawEvent","Publishers":["price-extractor"],"Subscribers":["price-loader"]},{"PubSubName":"product-distribution-pubsub","TopicName":"product-raw","ContractTypeName":"Intropy.Topology.Test.RawEvent","Publishers":["pim-extractor"],"Subscribers":["product-loader"]}],"Connectors":[{"Name":"erp","Transport":{"$transport":"sftp","DaprType":"bindings.sftp"},"DaprComponentName":"binding.erp","Directions":[1],"UsedBy":["pricing-service","product-loader"]},{"Name":"pim","Transport":{"$transport":"sftp","DaprType":"bindings.sftp"},"DaprComponentName":"binding.pim","Directions":[0],"UsedBy":["pim-extractor","pricing-service"]}],"Services":[]}""";

        // Act
        var json = JsonSerializer.Serialize(DeclareSystem().Build());

        // Assert
        Assert.Equal(expected, json);
    }

    [Fact]
    public void Serialize_WithSampleSystem_ShouldRoundTrip()
    {
        // Arrange
        var topology = DeclareSystem().Build();

        // Act
        var json = JsonSerializer.Serialize(topology);
        var deserialized = JsonSerializer.Deserialize<SystemTopology>(json);

        // Assert
        Assert.NotNull(deserialized);
        Assert.Equal(topology.SystemName, deserialized.SystemName);
        Assert.Equal(topology.Components.Count, deserialized.Components.Count);
        Assert.Equal("*/5 * * * *", deserialized.Components[0].Schedule);
